  --color-secondary-900: #f9fafb;
}

/* Base Component Styles */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-family-primary);
  font-weight: 500;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
  user-select: none;

  &:focus-visible {
    outline: 2px solid var(--color-primary-500);
